import type { LessonContent, TraceStep } from '../schema';

const code = String.raw;

/**
 * PL15 非同步：Promise、async／await 與事件迴圈. Every example and the reference solutions run in
 * tests/curriculum-code.test.ts (C++17, Java 17, Python 3, Node.js); the exercise's expected outputs were generated by
 * running the reference solutions. All outputs are deterministic: JavaScript relies only on the spec-defined order of
 * synchronous code, microtasks and setTimeout(…, 0) tasks; Python asyncio only on `await asyncio.sleep(0)` and gather's
 * result order; Java and C++ print only after join()/get(), never in the order threads happen to finish.
 */

// ---- the event-loop trace -----------------------------------------------------------------------------------------
/** The traced program; its real `node` output equals the last step's output (checked by the lesson's test). */
export const EVENT_LOOP_JS = code`console.log("script start");
setTimeout(() => {
    console.log("timeout");
    queueMicrotask(() => console.log("micro from timeout"));
}, 0);
async function work() {
    console.log("work start");
    await null;
    console.log("work resumed");
}
work();
Promise.resolve().then(() => console.log("then"));
console.log("script end");`;

/** One statement of the traced program as the event loop sees it: print, schedule a task or microtask, call, await. */
type Op = { line: number; note?: string } & ({ log: string } | { timeout: string } | { micro: string } | { call: string } | { await: string });
/** A piece of code that runs on the call stack in one go: the script, a function until its first await, a callback. */
interface Job { frame: string; line: number; leave: number; enter?: string; ops: Op[] }

const JOBS: Record<string, Job> = {
  script: { frame: '主程式', line: 1, leave: 13, ops: [
    { line: 1, log: 'script start' },
    { line: 2, timeout: 'timer', note: '`setTimeout(…, 0)` 不會立刻執行回呼：它把回呼交給計時器，到期（這裡是 0 毫秒後）就放進任務佇列的尾端。延遲是 0 也一樣要排隊，等目前的任務和所有微任務都做完。' },
    { line: 11, call: 'work' },
    { line: 12, micro: 'then', note: '`Promise.resolve()` 是已經完成的 Promise，所以 `.then` 的回呼立刻變成一個微任務。它排在 work 的後半之後，因為 work 在第 8 行先排了隊。' },
    { line: 13, log: 'script end', note: '印出 script end。到這裡為止全是同步程式：兩個佇列裡的回呼一個都還沒執行。' },
  ] },
  work: { frame: 'work()', line: 11, leave: 10, enter: '`work()` 是一般的同步呼叫：async 函式在第一個 await 之前，和普通函式一樣立刻執行。', ops: [
    { line: 7, log: 'work start' },
    { line: 8, await: 'resume', note: '`await null`：work 在這裡暫停。await 之後的程式（第 9 行起）被排進微任務佇列，work() 先回傳一個還沒完成的 Promise 並離開呼叫堆疊，主程式接著執行第 12 行。' },
  ] },
  resume: { frame: 'work（await 之後）', line: 9, leave: 10, enter: 'work 從 await 的下一行恢復，它的區域狀態都還在：暫停的函式不佔用呼叫堆疊，恢復時才重新放上去。', ops: [
    { line: 9, log: 'work resumed' },
  ] },
  then: { frame: 'then 回呼', line: 12, leave: 12, ops: [{ line: 12, log: 'then' }] },
  timer: { frame: 'setTimeout 回呼', line: 2, leave: 5, enter: '0 毫秒早就到了，但計時器回呼是任務，必須等前一個任務（整段主程式）與它之後的所有微任務都做完才輪到。', ops: [
    { line: 3, log: 'timeout' },
    { line: 4, micro: 'inner', note: '`queueMicrotask` 在任務執行中加入一個微任務：這個任務結束後、下一個任務開始前，它就會執行。' },
  ] },
  inner: { frame: 'queueMicrotask 回呼', line: 4, leave: 4, ops: [{ line: 4, log: 'micro from timeout' }] },
};

/**
 * Runs the event-loop rules on JOBS and records every step: the script is the first task; a task runs to the end on the
 * call stack; then the whole microtask queue is drained (including microtasks added meanwhile); then the next task.
 */
function eventLoopSteps(jobs: Record<string, Job>, first: string): TraceStep[] {
  const stack: string[] = [], micro: string[] = [], tasks: string[] = [first], printed: string[] = [];
  const steps: TraceStep[] = [];
  const snap = (line: number, note: string, added?: 'micro' | 'task') => steps.push({ line, note,
    containers: [
      { name: '呼叫堆疊', kind: 'stack', items: [...stack], marks: stack.length ? [{ at: stack.length - 1, kind: 'current' }] : [] },
      { name: '微任務佇列', kind: 'queue', items: micro.map(j => jobs[j].frame), marks: added === 'micro' ? [{ at: micro.length - 1, kind: 'write' }] : [] },
      { name: '任務佇列', kind: 'queue', items: tasks.map(j => jobs[j].frame), marks: added === 'task' ? [{ at: tasks.length - 1, kind: 'write' }] : [] },
    ],
    ...(printed.length ? { output: printed.join('\n') } : {}) });
  let draining = false;
  const next = () => stack.length ? `回到 ${stack[stack.length - 1]} 繼續執行。`
    : micro.length ? (draining ? '呼叫堆疊空了，微任務佇列還有東西：繼續執行下一個微任務，任務佇列仍要等。' : '呼叫堆疊空了：事件迴圈先清空微任務佇列，才會去拿下一個任務。')
    : tasks.length ? '呼叫堆疊空了，微任務佇列也是空的：事件迴圈從任務佇列取出下一個任務。'
    : '呼叫堆疊與兩個佇列都空了，程式結束。';
  const run = (name: string, why: string) => {
    const job = jobs[name];
    stack.push(job.frame);
    snap(job.line, job.enter ? `${why}${job.enter}` : why);
    for (const op of job.ops) {
      if ('log' in op) { printed.push(op.log); snap(op.line, op.note ?? `印出 ${op.log}。`); }
      else if ('timeout' in op) { tasks.push(op.timeout); snap(op.line, op.note ?? `${jobs[op.timeout].frame} 排進任務佇列。`, 'task'); }
      else if ('micro' in op) { micro.push(op.micro); snap(op.line, op.note ?? `${jobs[op.micro].frame} 排進微任務佇列。`, 'micro'); }
      else if ('call' in op) run(op.call, '');
      else { micro.push(op.await); stack.pop(); snap(op.line, op.note ?? `${job.frame} 在 await 暫停。`, 'micro'); return; }
    }
    stack.pop();
    snap(job.leave, `${job.frame} 執行完畢，離開呼叫堆疊。${next()}`);
  };
  while (tasks.length) {
    const task = tasks.shift()!;
    draining = false;
    run(task, steps.length ? `事件迴圈從任務佇列前端取出 ${jobs[task].frame}，放上呼叫堆疊。`
      : '整段程式本身就是第一個任務：放上呼叫堆疊，從第 1 行同步執行到最後一行，中途不會被任何回呼打斷。');
    draining = true;
    while (micro.length) {
      const job = micro.shift()!;
      run(job, `從微任務佇列前端取出 ${jobs[job].frame}，放上呼叫堆疊。`);
    }
  }
  return steps;
}

